/* Lifeline child care and character inclinations; independent of family wealth. */
(function(root){
'use strict';
const climates={warm:{name:'Тёплая атмосфера',happiness:88,energy:96},busy:{name:'Взрослые заняты, но заботятся о вас',happiness:82,energy:92},reserved:{name:'Спокойная забота',happiness:82,energy:92},harsh:{name:'Напряжённая атмосфера дома',happiness:55,energy:58}};
const focuses=[{id:'child-play',title:'Играть во всё',hint:'Формирует игривость',trait:'playfulness',label:'Игривость'},{id:'child-follow',title:'Ходить хвостиком',hint:'Формирует привязанность',trait:'attachment',label:'Привязанность'},{id:'child-explore',title:'Изучать каждый угол',hint:'Формирует любознательность',trait:'curiosity',label:'Любознательность'},{id:'child-myself',title:'Я сам!',hint:'Формирует самостоятельность',trait:'autonomy',label:'Самостоятельность'}];
const definitions=[{id:'child-care-rest',title:'Отдохнуть',baby:'Позвать взрослых',text:'Вы отдохнули, и вам стало спокойнее.',effect:{hl:2,h:4},energy:15},{id:'child-care-play',title:'Поиграть',baby:'Послушать знакомый голос',text:'Знакомая игра подняла вам настроение.',effect:{h:6}},{id:'child-care-close',title:'Попросить внимания',baby:'Попроситься на руки',text:'Вы побыли рядом с близкими и почувствовали поддержку.',effect:{so:5,h:3}},{id:'child-care-explore',title:'Исследовать мир',baby:'Прислушаться к звукам',text:'Вы заметили что-то новое в знакомом мире.',effect:{sm:3,h:2}}];
const month=()=>Math.max(0,S.age*12+Math.floor((S.t||0)*12+1e-7));
function initialize(tone,first=false){if(!S.lifelineChildCare){const climate=Object.hasOwn(climates,tone)?tone:'warm';S.lifelineChildCare={version:1,tone:climate,energy:climates[climate].energy,lastMonth:month(),focus:'child-play',traits:{playfulness:0,attachment:0,curiosity:0,autonomy:0},actionYear:S.age,used:0,ids:[]};if(first&&S.age<6)S.st.h=climates[climate].happiness;}return S.lifelineChildCare;}
function observe(){const c=initialize(),end=Math.min(72,month()),from=Math.min(72,c.lastMonth);if(end<=from)return;const climate=climates[c.tone]||climates.warm;for(let n=from+1;n<=end;n++){if(c.tone==='harsh'){if(S.st.h>climate.happiness)S.st.h=Math.max(climate.happiness,S.st.h-.7);}else if(S.st.h<climate.happiness)S.st.h=Math.min(climate.happiness,S.st.h+1);c.energy+=Math.max(-2,Math.min(2,climate.energy-c.energy));if(n>12){const f=focuses.find(f=>f.id===c.focus)||focuses[0];c.traits[f.trait]=Math.min(20,(c.traits[f.trait]||0)+.25);if(!S.trait&&n<=48){const key={playfulness:'act',attachment:'warm',curiosity:'cur',autonomy:'grit'}[f.trait];S.flags=S.flags||{};S.flags.tmp=S.flags.tmp||{};S.flags.tmp[key]=(S.flags.tmp[key]||0)+.025;}}}c.lastMonth=end;}
function focusOptions(){return S.age>=1&&S.age<6?focuses.map(({trait,label,...f})=>f):[];}
function setFocus(id){if(!focuses.some(f=>f.id===id))return false;if(S.age<1||S.age>=6||S.phase!=='life')throw Error('Этот приоритет сейчас недоступен');initialize().focus=id;return true;}
function actions(){if(!S||S.age>=6||S.phase==='dead')return [];const c=initialize(),record=c.actionYear===S.age?c:{used:0,ids:[]};return definitions.map(d=>({id:d.id,title:S.age<1?d.baby:d.title,cost:0,note:'Без затрат',disabled:record.ids.includes(d.id)||record.used>=2,reason:record.ids.includes(d.id)?'Уже выбрано в этом году':record.used>=2?'Следующие действия — в новом году':''}));}
function perform(id){const d=definitions.find(item=>item.id===id);if(!d)return false;if(!S||S.phase!=='life'||S.age>=6||S.pending||root.LifelineMoments?.pending())throw Error('Сейчас это действие недоступно');const available=actions().find(item=>item.id===id);if(!available||available.disabled)throw Error(available?.reason||'Сейчас это действие недоступно');const c=initialize();if(c.actionYear!==S.age){c.actionYear=S.age;c.used=0;c.ids=[];}c.used++;c.ids.push(id);for(const [key,value]of Object.entries(d.effect))S.st[key]=Math.max(0,Math.min(100,S.st[key]+value));if(d.energy)c.energy=Math.min(100,c.energy+d.energy);log(d.text,'warm');return true;}
function summary(){const c=initialize();return {label:climates[c.tone]?.name||climates.warm.name,energy:S.age<6?c.energy:100,focus:c.focus,traits:focuses.map(f=>({id:f.trait,label:f.label,value:c.traits[f.trait]||0})).filter(t=>t.value>0)};}
root.LifelineChildCare={initialize,observe,actions,perform,focusOptions,setFocus,summary};
})(self);
